51	std::string number_text(double value)
52	{
53	    std::ostringstream out;
54	    out.precision(2);
55	    out << std::fixed << value;
56	    std::string text = out.str();
57	    while (text.size() > 3 && text.back() == '0')
58	        text.pop_back();
59	    return text;
60	}
61	
62	// "0.2, 0.4, 0.6 and 0.8 mm"
63	std::string sizes_text(const std::vector<double>& nozzles)
64	{
65	    std::string text;
66	    for (std::size_t i = 0; i < nozzles.size(); ++i)
67	        text += (i == 0 ? "" : i + 1 == nozzles.size() ? " and " : ", ") + number_text(nozzles[i]);
68	    return text + " mm";
69	}
