71	// A nozzle of null or 0 is the model leaving it unsaid.
72	bool said_nozzle(const json& arguments)
73	{
74	    return arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.;
75	}
