244	const CatalogPrinter* PrinterConversation::catalog_entry(const std::string& id) const
245	{
246	    const std::vector<CatalogPrinter>& catalog = m_backend.catalog();
247	    const auto entry = std::find_if(catalog.begin(), catalog.end(), [&id](const CatalogPrinter& printer) { return printer.id == id; });
248	    return entry == catalog.end() ? nullptr : &*entry;
