251	json PrinterConversation::printer_json(const SavedPrinter& printer) const
252	{
253	    return json{{"name", printer.name},
254	                {"model", printer.model},
255	                {"nozzle", printer.nozzle},
256	                {"nozzles", printer.nozzles},
257	                {"spools", spools_json(printer.spools)},
258	                {"connected", printer.connected}};
259	}
260	
261	json PrinterConversation::context_json() const
262	{
263	    json context = json::object();
264	    if (m_mode == ConversationMode::Add) {
265	        json printers = json::array();
266	        for (const CatalogPrinter& printer : m_backend.catalog())
267	            printers.push_back(json::array({printer.id, printer.display_name(), printer.build_volume}));
268	        json network = json::array();
269	        for (const DiscoveredPrinter& found : m_network)
270	            network.push_back(json{{"name", found.name}, {"serial", found.stable_id}});
271	        context["printers"] = std::move(printers);
272	        context["network"]  = std::move(network);
273	    }
274	    if (const SavedPrinter printer = about(); !printer.name.empty()) {
275	        context["printer"]             = printer_json(printer);
276	        context["printer"]["provider"] = printer.vendor_id == "BBL" ? "bambu" : "host";
277	        if (printer.stock) {
278	            context["printer"]["stock"]    = true;
279	            context["printer"]["copyName"] = printer.copy_name;
280	        }
281	        if (m_needs_plugin)
282	            context["printer"]["needsNetworkPlugin"] = true;
283	    }
284	    return context;
285	}
286	
287	Agent::AgentSessionProfile PrinterConversation::profile() const
288	{
289	    Agent::AgentSessionProfile profile;
290	    // The tools are the app's to decide; the words are the page's
291	    // (printerInstructions.ts), sent with printer_instructions.
292	    profile.tool_names = session_tools();
293	    const std::vector<std::string> settings = settings_tools();
294	    profile.tool_names.insert(profile.tool_names.end(), settings.begin(), settings.end());
295	    profile.instructions = m_instructions;
296	    // This conversation is about a machine, not about the open project, and
297	    // what the app does on its own reaches the model as notes.
298	    profile.include_workspace          = false;
299	    return profile;
300	}
301	
302	json PrinterConversation::state_json() const
303	{
304	    json state{{"mode", m_mode == ConversationMode::Add ? "add" : m_mode == ConversationMode::Connect ? "connect" : "change"},
305	               {"printerName", m_printer_name}, {"blocks", m_blocks}, {"context", context_json()}};
306	    if (m_form)
307	        state["form"] = form_json();
308	    if (!m_credential_action.empty())
309	        state["credentialRequest"] = json{{"actionId", m_credential_action},
310	                                           {"target", m_credential_arguments.at("target")},
311	                                           {"provider", m_credential_arguments.at("provider")}};
312	    return state;
313	}
314	
315	// -- The session's tools ----------------------------------------------------
316	
317	std::optional<ToolError> PrinterConversation::preflight_tool(ToolHandler handler, ToolActivity& activity) const
318	{
319	    // Every session is offered every printer tool, so the tool list stays the
320	    // same for the prompt cache; what a call may do depends on the session.
321	    // Finding and adding a printer belongs to an Add session: a Change or
322	    // Connect session is about a printer the person already has, and an add
323	    // there would save another printer and move the session onto it.
324	    if (m_mode != ConversationMode::Add && (handler == ToolHandler::PrinterIdentify || handler == ToolHandler::PrinterAdd))
325	        return ToolError{"not_in_this_conversation",
326	                         "This conversation is about " + m_printer_name + ", which is already set up; printers are not "
327	                         "found or added here. Tell the person that another printer is added with + Add printer on Home."};
328	    // The settings tools reach the project too; here they reach this
329	    // printer's own settings, and nothing else.
330	    if (handler == ToolHandler::SettingsSearch || handler == ToolHandler::SettingsGet ||
331	        handler == ToolHandler::SettingsPreviewPatch || handler == ToolHandler::SettingsApplyPatch) {
332	        if (m_printer_name.empty())
333	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
334	        const json arguments = json::parse(activity.arguments_json);
335	        if (arguments.value("scope", std::string()) != "printer")
336	            return ToolError{"not_in_this_conversation", "Only this printer's settings are changed here: pass scope printer and "
337	                                                         "target.preset \"" + m_printer_name + "\"."};
338	        if (arguments.at("target").value("preset", std::string()) != m_printer_name)
339	            return ToolError{"other_printer", "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
340	                                              "changed from Printer settings… in its menu on Home."};
341	        return std::nullopt;
342	    }
343	    // A stock profile holds nothing of the person's own: a nozzle size or a
344	    // connection is saved on a printer they have added.
345	    if (about().stock && (handler == ToolHandler::PrinterChange || handler == ToolHandler::PrinterConnect ||
346	                          handler == ToolHandler::PrinterConnectionStatus))
347	        return ToolError{"stock_profile", "\"" + m_printer_name + "\" is the settings JusPrin comes with for this model, not a "
348	                                          "printer the person has added, so its nozzle and connection are not saved. Its other "
349	                                          "settings are changed by saving a copy, which is then theirs (settings_apply_patch with "
350	                                          "persistAs). To keep a nozzle or a connection, they add the printer with + Add printer "
351	                                          "on Home."};
352	    // A change is to the printer this session is about, and only once there
353	    // is one. The model sometimes names a printer on the network instead.
354	    if (handler == ToolHandler::PrinterChange) {
355	        if (saved(m_printer_name).name.empty())
356	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
357	        const std::string name = json::parse(activity.arguments_json).value("printerName", std::string());
358	        if (name != m_printer_name)
359	            return ToolError{saved(name).name.empty() ? "unknown_printer" : "other_printer",
360	                             "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
361	                             "changed from Printer settings… in its menu on Home."};
362	        return std::nullopt;
363	    }
364	    if (handler != ToolHandler::PrinterConnect)
365	        return std::nullopt;
366	    json              arguments = json::parse(activity.arguments_json);
367	    const std::string name      = m_printer_name;
368	    if (saved(name).name.empty())
369	        return ToolError{"no_printer", "There is no saved printer to connect yet: add one first."};
370	
371	    const PrinterConnectionInfo info = m_backend.connection(name);
372	    // No printer can be listed without the plug-in, so the reason is that,
373	    // not an unknown device.
374	    if (info.needs_network_plugin)
375	        return ToolError{"connection_unavailable", info.message};
376	    if (info.provider == "bambu") {
377	        // The person names the printer as its list shows it, so its name
378	        // finds it as surely as its id.
379	        const std::string device = arguments.value("deviceId", std::string());
380	        const auto found = std::find_if(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& candidate) {
381	            return candidate.lan_mode && (candidate.id == device || candidate.name == device);
382	        });
383	        if (found == info.candidates.end()) {
384	            std::string listed;
385	            for (const ConnectionCandidate& candidate : info.candidates)
386	                if (candidate.lan_mode)
387	                    listed += (listed.empty() ? "" : ", ") + candidate.id + " (" + candidate.name + ")";
388	            return ToolError{"unknown_device", listed.empty() ? "No printer in LAN mode is on the network now; check again with printer_connection_status." :
389	                                                                "Pass the deviceId of one of these printers in LAN mode: " + listed + "."};
390	        }
391	        activity.title = "Connect to " + found->name;
392	        arguments["deviceId"] = found->id;
393	        arguments["target"]   = found->name;
394	    } else if (info.provider == "host") {
395	        // The registry has already refused a hostType without an address; a
396	        // deviceId here names a Bambu Lab printer this one is not.
397	        if (!arguments.contains("hostType"))
398	            return ToolError{"address_needed", "Pass hostType and the address the person gave."};
399	        activity.title      = "Connect to " + arguments["address"].get<std::string>();
400	        arguments["target"] = arguments["address"];
401	    } else
402	        return ToolError{"connection_unavailable", info.message};
403	    // Which field the local form asks for, and the printer it named.
404	    arguments["provider"]    = info.provider;
405	    arguments["printerName"] = name;
406	    activity.arguments_json = arguments.dump();
407	    return std::nullopt;
408	}
409	
410	Result PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
411	{
412	    const json arguments = json::parse(activity.arguments_json);
413	    switch (handler) {
414	    case ToolHandler::PrinterIdentify: return identify(arguments, activity.correlation_id);
415	    case ToolHandler::PrinterAdd: return add(arguments, activity.correlation_id);
416	    case ToolHandler::PrinterChange: return change(arguments);
417	    case ToolHandler::PrinterConnectionStatus: return connection_status(m_printer_name, activity.correlation_id);
418	    case ToolHandler::PrinterConnect: return request_credential(arguments, activity.action_id);
419	    default: return {};
420	    }
421	}
422	
423	std::optional<json> PrinterConversation::tool_output(const ToolActivity& activity) const
424	{
425	    const std::vector<std::string> tools = session_tools();
426	    if (std::find(tools.begin(), tools.end(), activity.tool) == tools.end())
427	        return std::nullopt;
428	    if (activity.state == Agent::ToolState::Succeeded)
429	        return json::parse(activity.result_json);
430	    if (activity.state == Agent::ToolState::Failed && activity.error)
431	        return json{{"error", json{{"code", activity.error->code}, {"message", activity.error->message}}}};
432	    return std::nullopt;
433	}
434	
435	void PrinterConversation::tool_settled(const ToolActivity& activity)
436	{
437	    if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
438	        return;
439	    const std::string saved_as = json::parse(activity.result_json).value("savedAs", std::string());
440	    if (saved_as.empty() || saved_as == m_printer_name)
441	        return;
442	    // Saved as a copy, which Orca selected in the preset's place: the
443	    // printer the person now has, and Home lists it.
444	    m_printer_name = saved_as;
445	    m_host.printers_changed(saved_as);
446	    m_host.session_changed();
447	}
448	
449	Result PrinterConversation::identify(const json& arguments, const std::string& message_id)
450	{
451	    std::vector<const CatalogPrinter*> printers;
452	    for (const json& id : arguments.at("catalogIds")) {
453	        const CatalogPrinter* printer = catalog_entry(id);
454	        if (printer == nullptr)
455	            return refuse("unknown_printer", "\"" + id.get<std::string>() + "\" is not on the printer list; copy it exactly from the printer list.");
456	        if (std::find(printers.begin(), printers.end(), printer) == printers.end())
457	            printers.push_back(printer);
458	    }
459	    if (printers.size() > kMaximumCandidates)
460	        return refuse("too_many", "More than three fit. Ask one question that narrows it down instead.");
461	    const bool stated = said_nozzle(arguments);
462	    for (const CatalogPrinter* printer : printers)
463	        if (stated && !ships(printer->nozzles, arguments["nozzle"].get<double>()))
464	            return unknown_nozzle(printer->nozzles, printer->display_name(), arguments["nozzle"].get<double>());
465	
466	    json cards = json::array();
467	    json found = json::array();
468	    const std::vector<SavedPrinter> mine = m_backend.saved_printers();
469	    for (const CatalogPrinter* printer : printers) {
470	        const double nozzle = stated ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
471	        const bool   yours  = std::any_of(mine.begin(), mine.end(), [&](const SavedPrinter& p) { return p.model_id == printer->model_id; });
472	        cards.push_back(json{{"catalogId", printer->id}, {"name", printer->display_name()},
473	                             {"buildVolume", printer->build_volume}, {"picture", picture_data_url(printer->picture)}});
474	        found.push_back(json{{"catalogId", printer->id},
475	                             {"brand", printer->vendor_name},
476	                             {"model", printer->model_name},
477	                             {"buildVolume", printer->build_volume},
478	                             {"nozzles", printer->nozzles},
479	                             {"assumed", json{{"nozzle", nozzle},
480	                                              {"plate", nullable(printer->default_plate)},
481	                                              {"filament", nullable(printer->filament_for(nozzle))}}},
482	                             {"alreadyYours", yours}});
483	    }
484	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
485	                            {"kind", "printers"}, {"printers", std::move(cards)}});
486	    m_host.session_changed();
487	    return ok(json{{"printers", std::move(found)}});
488	}
489	
490	Result PrinterConversation::add(const json& arguments, const std::string& message_id)
491	{
492	    const std::string     id      = arguments.at("catalogId");
493	    const CatalogPrinter* printer = catalog_entry(id);
494	    if (printer == nullptr)
495	        return refuse("unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list.");
496	    const double nozzle = said_nozzle(arguments) ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
497	    if (!ships(printer->nozzles, nozzle))
498	        return unknown_nozzle(printer->nozzles, printer->display_name(), nozzle);
499	    // A second yes to the same printer is the same printer, not another one.
500	    if (const auto added = m_added.find(id); added != m_added.end())
501	        return refuse("already_added", "This conversation already added " + printer->display_name() + " as \"" + added->second +
502	                                           "\". To change it, use printer_change. A second printer of the same model is added by "
503	                                           "opening Add printer again.");
504	
505	    // Adding never authenticates: credentials belong to connecting, so a
506	    // failed connection cannot repeat this save.
507	    AddPrinterRequest request{printer->vendor_id,           printer->model_id,        number_text(nozzle),
508	                              printer->filament_for(nozzle), printer->display_name(), {}};
509	    SavedPrinter      added;
510	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
511	        return refuse("add_failed", problem);
512	    const SavedPrinter now = saved(added.name);
513	    if (now.name.empty())
514	        throw std::logic_error("A successful add did not save a printer");
515	    m_printer_name = now.name;
516	    m_added[id]    = now.name;
517	    // The receipt is the app's, drawn from what was saved: the model's reply
518	    // can word the moment any way, but whether it happened is not its to say.
519	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
520	                            {"kind", "added"}, {"printer", json{{"name", now.name}, {"nozzle", now.nozzle}}}});
521	    m_host.printers_changed(now.name);
522	    m_host.session_changed();
523	    return ok(json{{"printer", printer_json(now)}});
524	}
525	
526	Result PrinterConversation::change(const json& arguments)
527	{
528	    // preflight_tool has checked that this is the session's own printer.
529	    const std::string  name = arguments.at("printerName");
530	    const SavedPrinter now  = saved(name);
531	    // What is loaded is the printer's to report, not the conversation's to
532	    // record: the nozzle is the one physical change this tool saves.
533	    if (!said_nozzle(arguments))
534	        return refuse("nothing_to_change", "Name the nozzle size that changed.");
535	    if (!now.nozzles.empty() && !ships(now.nozzles, arguments["nozzle"].get<double>()))
536	        return unknown_nozzle(now.nozzles, now.model.empty() ? now.name : now.model, arguments["nozzle"].get<double>());
537	
538	    ChangePrinterRequest request;
539	    request.name = name;
540	    if (arguments["nozzle"].get<double>() != now.nozzle)
541	        request.nozzle = arguments["nozzle"].get<double>();
542	    if (!request.nozzle)
543	        return refuse("nothing_to_change", "That is already how " + name + " is set up.");
544	
545	    SavedPrinter             changed;
546	    std::vector<std::string> discarded;
547	    if (const std::string problem = m_backend.change_printer(request, changed, discarded); !problem.empty())
548	        return refuse("change_failed", problem);
549	    const SavedPrinter after = saved(name);
550	    json               what  = json::array();
551	    what.push_back(json{{"field", "nozzle"}, {"before", now.nozzle}, {"after", after.nozzle}});
552	    m_host.printers_changed();
553	    m_host.session_changed();
554	    return ok(json{{"changed", std::move(what)}, {"discarded", discarded}, {"printer", printer_json(after)}});
555	}
