583	void PrinterConversation::connect(const json& arguments, const std::string& credential)
584	{
585	    const std::string name   = arguments.at("printerName");
586	    const std::string target = arguments.at("target");
587	    const std::string problem =
588	        arguments.at("provider") == "bambu" ?
589	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
590	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
591	    if (!problem.empty()) {
592	        m_host.post_note("Connection to " + target + " failed: " + problem);
593	        m_host.session_changed();
594	        m_host.start_turn();
595	        return;
596	    }
597	    m_connecting = name;
598	    m_last_look  = {};
599	    m_host.session_changed();
600	}
601	
602	void PrinterConversation::abandon_connection()
603	{
604	    if (m_connecting.empty())
605	        return;
606	    m_backend.cancel_connection(m_connecting);
607	    m_connecting.clear();
608	}
609	
610	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
611	{
612	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
613	        m_form->options = m_form->reading.get();
614	        m_host.session_changed();
615	    }
616	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
617	        return;
618	    m_last_look = now;
619	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
620	    if (info.state == "connecting")
621	        return;
622	    const std::string name = m_connecting;
623	    m_connecting.clear();
624	    m_host.post_note(info.state == "verified" ? "Connection to " + name + " verified." :
625	                                                "Connection to " + name + " failed: " + info.message);
626	    m_host.printers_changed();
627	    m_host.session_changed();
628	    m_host.start_turn();
629	}
