28	// A printer already saved in this app: an Orca user printer profile, with the
29	// facts it was set up with.
30	struct SavedPrinter
31	{
32	    std::string               name;
33	    std::string               device_id;
34	    std::string               model;        // display model name
35	    std::string               model_id;     // profile model id
36	    std::string               vendor_id;
37	    std::string               picture;      // cover image path, may be empty
38	    double                    nozzle{0.};
39	    std::vector<double>       nozzles;      // sizes this model ships
40	    std::string               plate;        // untranslated plate name
41	    std::string               ams;          // "AMS lite", "AMS", or empty
42	    std::vector<PrinterSpool> spools;
43	    std::string               activity;     // offline, idle, printing, or empty
44	    bool                      connected{false};
45	    // One of OrcaSlicer's own printer profiles, selected in the project, not
46	    // a printer the person saved: nothing is saved on it, and a change to its
47	    // settings is saved as a copy under `copy_name`, which is then theirs.
48	    bool                      stock{false};
49	    std::string               copy_name;
50	};
51	
52	// What the packaged profiles offer, one entry per model.
53	struct CatalogPrinter
54	{
55	    std::string         id; // catalogue id, stable for this session
56	    std::string         vendor_id;
57	    std::string         vendor_name;  // the brand, as its vendor file names it
58	    std::string         model_id;     // the profile's own name, which Orca installs by
59	    std::string         model_name;   // that name with the brand not repeated
60	    std::string         device_model_id;
61	    std::string         build_volume; // "180 × 180 × 180 mm"
62	    std::string         picture;
63	    std::string         default_plate; // empty: the profile names none
64	    std::vector<double> nozzles;
65	    // The machine profile's own default filament for each nozzle size, in
66	    // the order of `nozzles`; empty where that profile names none.
67	    std::vector<std::string> filaments;
68	
69	    std::string display_name() const { return vendor_name + " " + model_name; }
70	    std::string filament_for(double nozzle) const
71	    {
72	        for (std::size_t i = 0; i < nozzles.size() && i < filaments.size(); ++i)
73	            if (nozzles[i] == nozzle)
74	                return filaments[i];
75	        return {};
76	    }
77	};
78	
79	// Everything the app needs to save a printer the person has just agreed to.
80	struct AddPrinterRequest
81	{
82	    std::string vendor_id;
83	    std::string model_id;
84	    std::string variant;  // nozzle size as the profile spells it, e.g. "0.4"
85	    std::string material; // default filament preset, may be empty
86	    std::string name;     // display name; empty uses the model name
87	    std::string device_id;    // a discovered printer's id, when this is one
88	    // The plate to start projects on, as OrcaSlicer's BedType value; absent
89	    // leaves the plate OrcaSlicer picks for the profile.
90	    std::optional<int> plate;
91	};
92	
93	// One build plate OrcaSlicer offers for a printer: its BedType value and the
94	// name OrcaSlicer shows for it.
95	struct PlateOption
96	{
97	    int         type{0};
98	    std::string label;
99	};
100	
101	// One filament preset the printer form offers.
102	struct FilamentOption
103	{
104	    std::string name;     // the preset's name, which installs and selects it
105	    std::string label;    // the name OrcaSlicer shows in its lists (the alias)
106	    std::string vendor;   // filament_vendor, e.g. "Generic", "eSUN"
107	    std::string material; // filament_type, e.g. "PLA"
108	    // Empty when OrcaSlicer counts it as fitting the printer; otherwise the
109	    // printers its profile names, as a phrase: "the Prusa CORE One and
110	    // Prusa XL", or "other printers" when it names none it can say.
111	    std::string made_for;
112	    // A person's own preset: the preset it was saved from, when it was.
113	    std::string base;
114	};
115	
116	// What the printer form offers for one model and nozzle, read from the
117	// packaged profiles as OrcaSlicer would load them. Nothing in it is
118	// installed until the person finishes the form.
119	struct SetupOptions
120	{
121	    std::string catalog_id;
122	    double      nozzle{0.};
123	    // Empty when OrcaSlicer offers no plate choice for this printer.
124	    std::vector<PlateOption> plates;
125	    int                      default_plate{0}; // the plate OrcaSlicer starts it on
126	    std::vector<FilamentOption> filaments;      // compatible, by label
127	    // The chosen brand's and OrcaSlicer's library filaments that do not fit
128	    // this printer, by label; picking one saves a copy for the printer.
129	    std::vector<FilamentOption> others;
130	    // The person's own filament presets, by name; `made_for` says which do
131	    // not fit, and picking one of those saves a copy for the printer.
132	    std::vector<FilamentOption> own;
133	    std::vector<std::string>    suggested;      // the model's default_materials that are compatible
134	    std::string                 default_filament; // the profile's own default; may be empty
135	    // Set when the profiles could not be read; nothing else is then.
136	    std::string error;
137	};
138	
139	// A correction to a printer that already exists. Every field is optional;
140	// what is left out stays as it is.
141	struct ChangePrinterRequest
142	{
143	    std::string                  name; // the saved printer to change
144	    std::optional<double>        nozzle;
145	};
