147	struct ConnectionCandidate
148	{
149	    std::string id;
150	    std::string name;
151	    std::string address;
152	    bool lan_mode{false};
153	};
154	
155	// How long a connection attempt waits for the printer before it is reported
156	// as failed. The model is told the same number when an attempt starts.
157	inline constexpr std::chrono::seconds kConnectionWait{30};
158	
159	struct PrinterConnectionInfo
160	{
161	    std::string provider{"unavailable"};
162	    std::string state{"not_configured"};
163	    std::string message;
164	    std::string device_id;
165	    std::vector<ConnectionCandidate> candidates;
166	    std::string address;
167	    std::string host_type;
168	    bool signed_in{false};
169	    bool nozzle_mismatch{false};
170	    // A Bambu Lab printer, on a computer where Bambu's network plug-in is not
171	    // installed or not turned on: nothing reaches the printer until it is.
172	    bool needs_network_plugin{false};
173	};
