181	class IPrinterBackend
182	{
183	public:
184	    virtual ~IPrinterBackend() = default;
185	
186	    // Reads. The catalogue is every model a person can add from this panel,
187	    // in a stable order.
188	    virtual const std::vector<CatalogPrinter>& catalog() const = 0;
189	    virtual std::vector<DiscoveredPrinter> network_printers() const = 0;
190	    // Every Bambu Lab printer the app has found and could set up, including
191	    // one it holds no access code for yet. network_printers() leaves those out.
192	    virtual std::vector<DiscoveredPrinter> nearby_printers() const { return network_printers(); }
193	    // The plates and filaments the printer form offers for one catalogue
194	    // model and nozzle. Called off the GUI thread: it reads files, and what
195	    // prepare_setup_options took of the person's own presets.
196	    virtual SetupOptions setup_options(const std::string& catalog_id, double nozzle) const = 0;
197	    // Takes what setup_options needs of the app's state, on the GUI thread,
198	    // before any setup_options call it is for.
199	    virtual void prepare_setup_options() {}
200	    // Puts `filament` in slot 1 of the printer just added and selected. With
201	    // `copy`, first saves a copy of it for that printer, which OrcaSlicer
202	    // keeps in the slot across printer changes; `used` names the preset now
203	    // in the slot. Returns a message for the person when it could not.
204	    virtual std::string start_with_filament(const std::string& printer, const std::string& filament, bool copy, std::string& used)
205	    {
206	        return "Choosing a filament is unavailable.";
207	    }
208	    // Opens OrcaSlicer's Create filament window for the printer just added
209	    // and selected, and puts a preset made there for it in slot 1. Returns
210	    // that preset's name, or an empty one when none was made for it.
211	    virtual std::string create_filament_preset(const std::string& printer) { return {}; }
212	    virtual std::vector<SavedPrinter>     saved_printers() const = 0;
213	    // A printer profile OrcaSlicer ships, by its preset name, as a person
214	    // could pick it; `stock` is set. An empty name when there is none.
215	    virtual SavedPrinter                  stock_printer(const std::string& name) const = 0;
216	
217	    // Writes. Each returns an empty string on success, or a message written
218	    // for the person explaining what stopped it. A change lists the keys of
219	    // the unsaved edits it dropped from the project's copy in `discarded`.
220	    virtual std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) = 0;
221	    virtual std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
222	                                       std::vector<std::string>& discarded) = 0;
223	    // Deletes a saved printer the way Home's "Remove printer…" does.
224	    virtual std::string remove_printer(const std::string& name) = 0;
225	
226	    // The ways to OrcaSlicer's own screens: its printer wizard for a new
227	    // printer (only where the printer form cannot be shown), its printer
228	    // settings for an existing one.
229	    virtual ManualPrinterResult run_manual_setup() = 0;
230	    virtual void open_printer_settings(const std::string& name) = 0;
231	
232	    // Connection is a separate operation against an existing saved printer.
233	    // Credentials are input-only and never part of a snapshot or conversation.
234	    // connect_printer and connect_host start an attempt and return at once;
235	    // connection() reports it as connecting until it settles, and a new
236	    // attempt replaces one still waiting. connect_host saves the address only
237	    // once the printer has answered.
238	    virtual PrinterConnectionInfo connection(const std::string& name) { return {}; }
239	    virtual void prepare_connection(const std::string& name) {}
240	    virtual void sign_in_to_bambu() {}
241	    // Downloads and loads Bambu's network plug-in behind Orca's own progress
242	    // dialog, as Orca's "Click here to install it" does. Returns once that
243	    // dialog closes, whether or not the plug-in is loaded then.
244	    virtual void install_network_plugin() {}
245	    virtual std::string connect_printer(const std::string& name, const std::string& device_id,
246	                                       const std::string& access_code) { return "Connection is unavailable."; }
247	    virtual std::string connect_host(const std::string& name, const std::string& host_type,
248	                                    const std::string& address, const std::string& api_key) { return "Connection is unavailable."; }
249	    // Abandons this printer's attempt if it is still waiting: whatever the
250	    // printer answers afterwards is dropped.
251	    virtual void cancel_connection(const std::string& name) {}
252	};
253	
254	} // namespace Slic3r::GUI::JusPrin::PrinterSetup
