20	// At most three candidates: more is a list to read rather than an answer.
21	constexpr std::size_t kMaximumCandidates = 3;
22	
23	// The Add instructions carry every printer, about 28 KB; well above that is
24	// not a prompt the page meant to send.
25	constexpr std::size_t kInstructionsLimit = 256 * 1024;
26	
27	// The opening is a sentence or two; a page that sends more has a bug, and
28	// none of it reaches the thread.
