51	std::string number_text(double value)
52	{
53	    std::ostringstream out;
54	    out.precision(2);
55	    out << std::fixed << value;
56	    std::string text = out.str();
57	    while (text.size() > 3 && text.back() == '0')
58	        text.pop_back();
59	    return text;
60	}
61	
62	// "0.2, 0.4, 0.6 and 0.8 mm"
63	std::string sizes_text(const std::vector<double>& nozzles)
64	{
65	    std::string text;
66	    for (std::size_t i = 0; i < nozzles.size(); ++i)
67	        text += (i == 0 ? "" : i + 1 == nozzles.size() ? " and " : ", ") + number_text(nozzles[i]);
68	    return text + " mm";
69	}
70	
71	// A nozzle of null or 0 is the model leaving it unsaid.
72	bool said_nozzle(const json& arguments)
73	{
74	    return arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.;
75	}
76	
77	bool ships(const std::vector<double>& nozzles, double nozzle)
78	{
79	    return std::find(nozzles.begin(), nozzles.end(), nozzle) != nozzles.end();
80	}
81	
82	Result unknown_nozzle(const std::vector<double>& nozzles, const std::string& model, double nozzle)
83	{
84	    return refuse("unknown_nozzle", "JusPrin supports " + sizes_text(nozzles) + " nozzles for " + model + ", but not " +
85	                                        number_text(nozzle) + " mm. Ask the person to check the nozzle marking or packaging; "
86	                                        "do not substitute a size.");
87	}
