94	std::string picture_data_url(const std::string& path)
95	{
96	    if (path.empty())
97	        return {};
98	    std::ifstream file(std::filesystem::u8path(path), std::ios::binary);
99	    std::ostringstream bytes;
100	    bytes << file.rdbuf();
101	    const std::string data = bytes.str();
102	    return data.empty() ? std::string() : "data:image/png;base64," + base64_encode(data);
103	}
