107	json spools_json(const std::vector<PrinterSpool>& spools)
108	{
109	    json list = json::array();
110	    for (const PrinterSpool& spool : spools) {
111	        json entry{{"name", spool.name}, {"material", spool.material}};
112	        if (!spool.colour.empty())
113	            entry["colour"] = spool.colour;
114	        list.push_back(std::move(entry));
115	    }
116	    return list;
117	}
