435	void PrinterConversation::tool_settled(const ToolActivity& activity)
436	{
437	    if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
438	        return;
439	    const std::string saved_as = json::parse(activity.result_json).value("savedAs", std::string());
440	    if (saved_as.empty() || saved_as == m_printer_name)
441	        return;
442	    // Saved as a copy, which Orca selected in the preset's place: the
443	    // printer the person now has, and Home lists it.
444	    m_printer_name = saved_as;
445	    m_host.printers_changed(saved_as);
446	    m_host.session_changed();
447	}
448	
449	Result PrinterConversation::identify(const json& arguments, const std::string& message_id)
450	{
451	    std::vector<const CatalogPrinter*> printers;
452	    for (const json& id : arguments.at("catalogIds")) {
453	        const CatalogPrinter* printer = catalog_entry(id);
454	        if (printer == nullptr)
455	            return refuse("unknown_printer", "\"" + id.get<std::string>() + "\" is not on the printer list; copy it exactly from the printer list.");
456	        if (std::find(printers.begin(), printers.end(), printer) == printers.end())
457	            printers.push_back(printer);
458	    }
459	    if (printers.size() > kMaximumCandidates)
460	        return refuse("too_many", "More than three fit. Ask one question that narrows it down instead.");
461	    const bool stated = said_nozzle(arguments);
462	    for (const CatalogPrinter* printer : printers)
463	        if (stated && !ships(printer->nozzles, arguments["nozzle"].get<double>()))
464	            return unknown_nozzle(printer->nozzles, printer->display_name(), arguments["nozzle"].get<double>());
465	
466	    json cards = json::array();
467	    json found = json::array();
468	    const std::vector<SavedPrinter> mine = m_backend.saved_printers();
469	    for (const CatalogPrinter* printer : printers) {
470	        const double nozzle = stated ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
471	        const bool   yours  = std::any_of(mine.begin(), mine.end(), [&](const SavedPrinter& p) { return p.model_id == printer->model_id; });
472	        cards.push_back(json{{"catalogId", printer->id}, {"name", printer->display_name()},
473	                             {"buildVolume", printer->build_volume}, {"picture", picture_data_url(printer->picture)}});
474	        found.push_back(json{{"catalogId", printer->id},
475	                             {"brand", printer->vendor_name},
476	                             {"model", printer->model_name},
477	                             {"buildVolume", printer->build_volume},
478	                             {"nozzles", printer->nozzles},
479	                             {"assumed", json{{"nozzle", nozzle},
480	                                              {"plate", nullable(printer->default_plate)},
481	                                              {"filament", nullable(printer->filament_for(nozzle))}}},
482	                             {"alreadyYours", yours}});
483	    }
484	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
485	                            {"kind", "printers"}, {"printers", std::move(cards)}});
486	    m_host.session_changed();
487	    return ok(json{{"printers", std::move(found)}});
488	}
489	
490	Result PrinterConversation::add(const json& arguments, const std::string& message_id)
491	{
492	    const std::string     id      = arguments.at("catalogId");
493	    const CatalogPrinter* printer = catalog_entry(id);
494	    if (printer == nullptr)
495	        return refuse("unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list.");
496	    const double nozzle = said_nozzle(arguments) ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
497	    if (!ships(printer->nozzles, nozzle))
498	        return unknown_nozzle(printer->nozzles, printer->display_name(), nozzle);
499	    // A second yes to the same printer is the same printer, not another one.
500	    if (const auto added = m_added.find(id); added != m_added.end())
501	        return refuse("already_added", "This conversation already added " + printer->display_name() + " as \"" + added->second +
502	                                           "\". To change it, use printer_change. A second printer of the same model is added by "
503	                                           "opening Add printer again.");
504	
505	    // Adding never authenticates: credentials belong to connecting, so a
506	    // failed connection cannot repeat this save.
507	    AddPrinterRequest request{printer->vendor_id,           printer->model_id,        number_text(nozzle),
508	                              printer->filament_for(nozzle), printer->display_name(), {}};
509	    SavedPrinter      added;
510	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
511	        return refuse("add_failed", problem);
512	    const SavedPrinter now = saved(added.name);
513	    if (now.name.empty())
514	        throw std::logic_error("A successful add did not save a printer");
515	    m_printer_name = now.name;
516	    m_added[id]    = now.name;
517	    // The receipt is the app's, drawn from what was saved: the model's reply
518	    // can word the moment any way, but whether it happened is not its to say.
519	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
520	                            {"kind", "added"}, {"printer", json{{"name", now.name}, {"nozzle", now.nozzle}}}});
521	    m_host.printers_changed(now.name);
522	    m_host.session_changed();
523	    return ok(json{{"printer", printer_json(now)}});
524	}
525	
526	Result PrinterConversation::change(const json& arguments)
527	{
528	    // preflight_tool has checked that this is the session's own printer.
529	    const std::string  name = arguments.at("printerName");
530	    const SavedPrinter now  = saved(name);
531	    // What is loaded is the printer's to report, not the conversation's to
532	    // record: the nozzle is the one physical change this tool saves.
533	    if (!said_nozzle(arguments))
534	        return refuse("nothing_to_change", "Name the nozzle size that changed.");
535	    if (!now.nozzles.empty() && !ships(now.nozzles, arguments["nozzle"].get<double>()))
536	        return unknown_nozzle(now.nozzles, now.model.empty() ? now.name : now.model, arguments["nozzle"].get<double>());
537	
538	    ChangePrinterRequest request;
539	    request.name = name;
540	    if (arguments["nozzle"].get<double>() != now.nozzle)
541	        request.nozzle = arguments["nozzle"].get<double>();
542	    if (!request.nozzle)
543	        return refuse("nothing_to_change", "That is already how " + name + " is set up.");
544	
545	    SavedPrinter             changed;
546	    std::vector<std::string> discarded;
547	    if (const std::string problem = m_backend.change_printer(request, changed, discarded); !problem.empty())
548	        return refuse("change_failed", problem);
549	    const SavedPrinter after = saved(name);
550	    json               what  = json::array();
551	    what.push_back(json{{"field", "nozzle"}, {"before", now.nozzle}, {"after", after.nozzle}});
552	    m_host.printers_changed();
553	    m_host.session_changed();
554	    return ok(json{{"changed", std::move(what)}, {"discarded", discarded}, {"printer", printer_json(after)}});
555	}
556	
557	Result PrinterConversation::connection_status(const std::string& name, const std::string& message_id)
558	{
559	    if (saved(name).name.empty())
560	        return refuse("no_printer", "There is no saved printer to connect yet: add one first.");
561	    // For a Bambu Lab printer this starts looking for it on the network --
562	    // once: starting again switches the printer agent and restarts discovery,
563	    // so a model that checks again would never let it find anything.
564	    if (m_prepared != name) {
565	        m_backend.prepare_connection(name);
566	        m_prepared = name;
567	    }
568	    const PrinterConnectionInfo info = m_backend.connection(name);
569	    if (info.needs_network_plugin)
570	        show_plugin_needed(message_id);
571	    return ok(connection_json(info));
572	}
573	
574	Result PrinterConversation::request_credential(const json& arguments, const std::string& action_id)
575	{
576	    m_credential_action    = action_id;
577	    m_credential_arguments = arguments;
578	    m_host.session_changed();
579	    return ok(json{{"state", "credential_requested"},
580	                   {"message", "The app is waiting for the person to enter the printer credential locally."}});
581	}
582	
583	void PrinterConversation::connect(const json& arguments, const std::string& credential)
584	{
585	    const std::string name   = arguments.at("printerName");
586	    const std::string target = arguments.at("target");
587	    const std::string problem =
588	        arguments.at("provider") == "bambu" ?
589	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
590	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
591	    if (!problem.empty()) {
592	        m_host.post_note("Connection to " + target + " failed: " + problem);
593	        m_host.session_changed();
594	        m_host.start_turn();
595	        return;
596	    }
597	    m_connecting = name;
598	    m_last_look  = {};
599	    m_host.session_changed();
600	}
601	
602	void PrinterConversation::abandon_connection()
603	{
604	    if (m_connecting.empty())
605	        return;
606	    m_backend.cancel_connection(m_connecting);
607	    m_connecting.clear();
608	}
609	
610	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
611	{
612	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
613	        m_form->options = m_form->reading.get();
614	        m_host.session_changed();
615	    }
616	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
617	        return;
618	    m_last_look = now;
619	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
620	    if (info.state == "connecting")
621	        return;
622	    const std::string name = m_connecting;
623	    m_connecting.clear();
624	    m_host.post_note(info.state == "verified" ? "Connection to " + name + " verified." :
625	                                                "Connection to " + name + " failed: " + info.message);
626	    m_host.printers_changed();
627	    m_host.session_changed();
628	    m_host.start_turn();
629	}
630	
631	// -- The panel's own page --------------------------------------------------
632	
633	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
634	{
635	    if (type == "printer_instructions") {
636	        // Bounded: the page's words become every request's system prompt.
637	        const std::string text = payload.value("text", std::string());
638	        if (text.size() <= kInstructionsLimit && text != m_instructions) {
639	            m_instructions = text;
640	            m_host.profile_changed();
641	        }
642	        return true;
643	    }
644	    if (type == "printer_opening") {
645	        // The first line is the page's to write and the app's to post, once:
646	        // a reloaded page asks again, and the thread already has it.
647	        const std::string text = payload.value("text", std::string());
648	        if (m_opened || text.empty() || text.size() > kNoteLimit)
649	            return true;
650	        m_opened                     = true;
651	        const std::string message_id = m_host.post_opening(text);
652	        for (json& entry : m_blocks)
653	            if (entry.value("afterMessageId", std::string()).empty())
654	                entry["afterMessageId"] = message_id;
655	        m_host.session_changed();
656	        return true;
657	    }
658	    if (type != "printer_action")
659	        return false;
660	
661	    const std::string action = payload.value("action", std::string());
662	    if (action == "close")
663	        m_host.close_panel();
664	    else if (action == "manual_setup")
665	        open_form();
666	    else if (action == "form_options")
667	        ask_form_options(payload);
668	    else if (action == "form_finish")
669	        finish_form(payload);
670	    else if (action == "form_close") {
671	        m_form.reset();
672	        m_host.session_changed();
673	    } else if (action == "orca_printer_list") {
674	        // OrcaSlicer's own printer list, for a panel whose page could not
675	        // load and so cannot show the form; what it added is news the model
676	        // answers.
677	        const ManualPrinterResult result = m_backend.run_manual_setup();
678	        if (!result.added.empty()) {
679	            m_printer_name = result.added.front().name;
680	            m_host.post_note("The person added " + m_printer_name + " from the printer list.");
681	            m_host.printers_changed(m_printer_name);
682	            m_host.session_changed();
683	            m_host.start_turn();
684	        }
685	    } else if (action == "connect" && payload.value("actionId", std::string()) == m_credential_action &&
686	               payload.contains("credential") && payload["credential"].is_string()) {
687	        const json arguments = std::move(m_credential_arguments);
688	        m_credential_action.clear();
689	        m_credential_arguments = json::object();
690	        connect(arguments, payload["credential"].get<std::string>());
691	    } else if (action == "open_printer_settings" && !m_printer_name.empty()) {
692	        m_backend.open_printer_settings(m_printer_name);
693	        m_host.printers_changed();
694	        m_host.session_changed();
695	    } else if (action == "undo_add")
696	        undo_add(payload.value("blockId", std::string()));
697	    else if (action == "install_network_plugin")
698	        install_network_plugin();
699	    return true;
700	}
701	
702	void PrinterConversation::undo_add(const std::string& block_id)
703	{
704	    json* receipt = nullptr;
705	    for (json& block : m_blocks)
706	        if (block.value("id", std::string()) == block_id && block.value("kind", std::string()) == "added")
707	            receipt = &block;
708	    // A second tap that arrived before the page redrew the first has nothing
709	    // left to undo.
710	    if (receipt == nullptr || receipt->value("removed", false))
711	        return;
712	
713	    // Orca's own delete, as Home's "Remove printer…" runs it: the printer the
714	    // project was set up for gives way to the profile it was based on.
715	    const std::string name = receipt->at("printer").at("name");
716	    if (const std::string problem = m_backend.remove_printer(name); !problem.empty()) {
717	        m_host.post_note("Undo did not remove " + name + ": " + problem);
718	        m_host.session_changed();
719	        return;
720	    }
721	    // printer_add saves a printer based on a shipped profile, which Orca
722	    // deletes without asking; only a printer of the person's own design can
723	    // be kept by declining there.
724	    if (!saved(name).name.empty())
725	        throw std::logic_error("Removing an added printer left it saved");
726	
727	    if (m_connecting == name)
728	        abandon_connection();
729	    (*receipt)["removed"] = true;
730	    // The same printer can now be added again, and nothing here is about it.
731	    for (auto added = m_added.begin(); added != m_added.end();)
732	        added = added->second == name ? m_added.erase(added) : std::next(added);
733	    if (m_printer_name == name)
734	        m_printer_name.clear();
735	    if (m_prepared == name)
736	        m_prepared.clear();
737	    m_host.post_note("The person tapped Undo on the receipt: " + name + " is removed and is no longer one of their printers.");
738	    m_host.printers_changed();
739	    m_host.session_changed();
740	    m_host.start_turn();
741	}
