    for (int fd = 0; fd < std::min(getdtablesize(), 4096); ++fd) {
        sockaddr_in address{};
        socklen_t   size = sizeof(address);
        int         type = 0;
        socklen_t   type_size = sizeof(type);
        if (getsockname(fd, reinterpret_cast<sockaddr*>(&address), &size) == 0 && address.sin_family == AF_INET &&
